101	static void write_wrapped(FILE* out, const std::string& s, int line_len) {
102	    if (line_len <= 0 || (int)s.size() <= line_len) {
103	        fwrite(s.data(), 1, s.size(), out);
104	        fputc('\n', out);
105	        return;
106	    }
107	    size_t i = 0;
108	    while (i < s.size()) {
109	        size_t n = s.size() - i < (size_t)line_len ? s.size() - i : (size_t)line_len;
110	        fwrite(s.data() + i, 1, n, out);
111	        fputc('\n', out);
112	        i += n;
113	    }
114	}
