#include "common.h"
#include <cstdio>

// seqtk listhet: extract the position of each het.
// A "het" is one of R Y S W K M (both cases). Output columns:
// sequence name, 1-based position, the het code itself.
int cmd_listhet(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: seqtk listhet <in.fa>\n");
        return 1;
    }
    SeqFile sf(argv[1]);
    if (!sf.is_open()) {
        fprintf(stderr, "[E::stk_listhet] failed to open the input file/stream.\n");
        return 1;
    }
    SeqRecord r;
    while (sf.next(r) == 1) {
        for (size_t i = 0; i < r.seq.size(); ++i) {
            char c = r.seq[i];
            switch (c) {
            case 'R': case 'Y': case 'S': case 'W': case 'K': case 'M':
            case 'r': case 'y': case 's': case 'w': case 'k': case 'm':
                printf("%s\t%lu\t%c\n", r.name.c_str(), (unsigned long)(i + 1), c);
                break;
            }
        }
    }
    return 0;
}
